<span class="line"><span style="color:#E5C07B;">        Func</span><span style="color:#ABB2BF;">&lt;</span><span style="color:#C678DD;">int</span><span style="color:#ABB2BF;">, </span><span style="color:#C678DD;">int</span><span style="color:#ABB2BF;">&gt; </span><span style="color:#E06C75;">fn</span><span style="color:#56B6C2;"> =</span><span style="color:#E5C07B;"> x</span><span style="color:#ABB2BF;"> =&gt; </span><span style="color:#E06C75;">x</span><span style="color:#56B6C2;"> *</span><span style="color:#E06C75;"> factor</span><span style="color:#ABB2BF;">;</span></span>
